		$fwrite(f, "%g,%b\n", $time, q);
    end

  end

  initial begin
    // [Auto-Moved Vars]
          reg [4:0] dly = $random;

    {rstn, clk, t, instrumented_clk} <= 0;
    //$monitor ("T=%0t rstn=%0b t=%0d q=%0d", $time, rstn, t, q);
    repeat(2)
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB
 @(posedge clk);
    rstn <= 1;

    for (integer i = 0; i < 20; i = i+1) begin

      #(dly) t <= $random;
    end
  // #20 $fclose(f);
  #20 $finish;
  end
  initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

#2000000
$finish;
end



// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. Stimuli
    $display("LLM Phase Started: T-Flip Flop Verification");

    // Initialize Inputs
    rstn = 0;
    t = 0;

    // Wait for system stabilization
    #10;

    // ------------------------------------------------------------
    // Test Case 1: Synchronous Reset Verification
    // ------------------------------------------------------------
    // Assert reset and wait for clock edges
    // q should remain 0
    for (i = 0; i < 3; i = i + 1) begin
        @(posedge clk);
    end

    // Release reset away from clock edge (negedge) to avoid races
    @(negedge clk);
    rstn = 1;

    // ------------------------------------------------------------
    // Test Case 2: Hold State (t=0)
    // ------------------------------------------------------------
    t = 0;
    @(posedge clk);
    // Expected: q = 0 (Hold)

    // ------------------------------------------------------------
    // Test Case 3: Toggle State (t=1) Transitions
    // ------------------------------------------------------------
    // Transition 0 -> 1
    @(negedge clk);
    t = 1;
    @(posedge clk);
    // Expected: q = 1

    // Transition 1 -> 0
    @(negedge clk);
    t = 1; // Keep t=1
    @(posedge clk);
    // Expected: q = 0

    // Transition 0 -> 1 again
    @(negedge clk);
    t = 1;
    @(posedge clk);
    // Expected: q = 1

    // ------------------------------------------------------------
    // Test Case 4: Hold State at High (q=1, t=0)
    // ------------------------------------------------------------
    @(negedge clk);
    t = 0;
    @(posedge clk);
    // Expected: q = 1 (Hold)

    // ------------------------------------------------------------
    // Test Case 5: Async Reset Mutation Detection
    // ------------------------------------------------------------
    // Current state: q=1.
    // We assert reset at negedge. 
    // Golden (Sync Reset): q stays 1 until posedge.
    // Mutated (Async Reset): q drops to 0 immediately at negedge.
    @(negedge clk);
    rstn = 0;
    #2; // Small delay to allow potential async reset to propagate

    // Complete the cycle to verify sync reset behavior
    @(posedge clk);
    // Expected: q = 0 (Reset applied synchronously)

    // Release reset
    @(negedge clk);
    rstn = 1;

    // ------------------------------------------------------------
    // Test Case 6: Deterministic Stress Pattern
    // ------------------------------------------------------------
    // Pattern: 1 (Toggle), 0 (Hold), 1 (Toggle), 1 (Toggle)

    // Toggle (0->1)
    @(negedge clk); t = 1; @(posedge clk);

    // Hold (1->1)
    @(negedge clk); t = 0; @(posedge clk);

    // Toggle (1->0)
    @(negedge clk); t = 1; @(posedge clk);

    // Toggle (0->1)
    @(negedge clk); t = 1; @(posedge clk);

    // ------------------------------------------------------------
    // Test Case 7: Input Stability/Glitch Test
    // ------------------------------------------------------------
    // Change t multiple times before clock edge.
    // Only the last value before setup time should matter.
    @(negedge clk);
    t = 0;
    #1 t = 1;
    #1 t = 0; // Final value 0 (Hold)
    @(posedge clk);
    // Expected: q holds previous value (1)

    // 3. Handover
    #100;
    $display("LLM Phase Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

